selector_to_html = {"a[href=\"#write-the-wrapper\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. \u7f16\u5199\u5c01\u88c5\u5c42 {#write-the-wrapper}<a class=\"headerlink\" href=\"#write-the-wrapper\" title=\"Link to this heading\">#</a></h2><p>\u6309\u7167\u5982\u4e0b\u6b65\u9aa4\u6dfb\u52a0\u4e00\u4e2a\u65b0\u7684 C++ \u5c01\u88c5\u7684\u7b97\u5b50\uff1a</p>", "a[href=\"#c\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u6dfb\u52a0 C++ \u5c01\u88c5\u7684\u7b97\u5b50<a class=\"headerlink\" href=\"#c\" title=\"Link to this heading\">#</a></h1><p>\u8981\u6dfb\u52a0\u4e00\u4e2a C++ \u5c01\u88c5\u7684\u7b97\u5b50\uff0c\u4f60\u9700\u8981\u9996\u5148\u5728\u5b89\u88c5 FlagGems \u65f6\u542f\u7528 C++ \u6269\u5c55\u80fd\u529b\u7279\u6027\u3002\n\u8bf7\u53c2\u9605<a class=\"reference internal\" href=\"#../getting-started/installation\"><span class=\"xref myst\">FlagGems \u5b89\u88c5</span></a>\u6587\u6863\uff0c\n\u4e86\u89e3\u5982\u4f55\u5728\u5b89\u88c5 <code class=\"docutils literal notranslate\"><span class=\"pre\">flag_gems</span></code> \u65f6\u542f\u7528 C++ \u6269\u5c55\u7684\u8be6\u7ec6\u6b65\u9aa4\u3002</p>", "a[href=\"#write-test-cases\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. \u7f16\u5199\u6d4b\u8bd5\u7528\u4f8b  {#write-test-cases}<a class=\"headerlink\" href=\"#write-test-cases\" title=\"Link to this heading\">#</a></h2><p>FlagGems \u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">ctest</span></code> \u548c <code class=\"docutils literal notranslate\"><span class=\"pre\">googletest</span></code> \u6765\u6267\u884c C++ \u4ee3\u7801\u7684\u5355\u5143\u6d4b\u8bd5\u3002\n\u5728\u5b8c\u6210 C++ \u5c01\u88c5\u7684\u7b97\u5b50\u5b9e\u73b0\u4e4b\u540e\uff0c\u4f60\u9700\u8981\u4e3a\u5176\u6dfb\u52a0\u5bf9\u5e94\u7684 C++ \u6d4b\u8bd5\u7528\u4f8b\u3002\n\u4f60\u7684\u6d4b\u8bd5\u7528\u4f8b\u5e94\u8be5\u6dfb\u52a0\u5230 <code class=\"docutils literal notranslate\"><span class=\"pre\">ctests/test_triton_&lt;xxx&gt;.cpp</span></code> \u6587\u4ef6\u4e2d\uff0c\n\u5e76\u4e14\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">ctests/CMakeLists.txt</span></code> \u4e2d\u5217\u51fa\u6d4b\u8bd5\u7528\u4f8b\u6587\u4ef6\u3002\n\u6700\u540e\uff0c\u6784\u5efa\u4f60\u7684\u6d4b\u8bd5\u4ee3\u7801\u5e76\u4f7f\u7528 <a class=\"reference internal\" href=\"#../testing/ctests\"><span class=\"xref myst\">C++ \u6d4b\u8bd5</span></a>\u6587\u6863\u4e2d\u6240\u7ed9\u65b9\u6cd5\u6765\u6267\u884c\u6d4b\u8bd5\u3002</p>", "a[href=\"#pr\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. \u4e3a\u4f60\u7684\u4ee3\u7801\u63d0\u4ea4 PR<a class=\"headerlink\" href=\"#pr\" title=\"Link to this heading\">#</a></h2><p>\u5f53\u6240\u6709\u4e00\u5207\u90fd\u5de5\u4f5c\u6b63\u5e38\u65f6\uff0c\u8be5\u5230\u63d0\u4ea4\u62c9\u53bb\u8bf7\u6c42\uff08Pull Request\uff0cPR\uff09\u7684\u65f6\u5019\u4e86\u3002\n\u5728\u63d0\u4ea4 PR \u65f6\uff0c\u6211\u4eec\u5e0c\u671b\u4f60\u5728\u9488\u5bf9\u7b97\u5b50\u6240\u505a\u7684\u5de5\u4f5c\u63d0\u4f9b\u7b80\u8981\u63cf\u8ff0\u4e4b\u5916\uff0c\n\u80fd\u591f\u5728 PR \u63cf\u8ff0\u4e2d\u5305\u542b\u7aef\u5230\u7aef\u7684\u6027\u80fd\u6d4b\u8bd5\u6570\u636e\u4ee5\u65b9\u4fbf\u8bc4\u5ba1\u3002</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. \u8fd0\u884c C++ \u6d4b\u8bd5\u7528\u4f8b<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>\u5982\u679c\u4f60\u5728\u6784\u9020 FlagGems \u65f6\u5c06 cmake \u9009\u9879 <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGGEMS_BUILD_CTESTS</span></code> \u8bbe\u7f6e\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">ON</span></code>\uff0c\n\u8fdb\u800c\u542f\u7528\u4e86 C++ \u6269\u5c55\uff0c\u90a3\u4e48\u4f60\u5c31\u53ef\u4ee5\u4f7f\u7528\u4e0b\u9762\u7684\u547d\u4ee4\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">FlagGems/build/cpython-3xx</span></code>\n\u76ee\u5f55\u4e0b\u8fd0\u884c ctest\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
